UPDATE companies SET enrichmentStatus = 'enriched' WHERE searchId = 750001 AND enrichmentStatus = 'failed' AND city IS NOT NULL AND city != '';

UPDATE companies SET enrichmentStatus = 'pending' WHERE searchId = 750001 AND enrichmentStatus = 'failed' AND (city IS NULL OR city = '');

SELECT enrichmentStatus, COUNT(*) as count FROM companies WHERE searchId = 750001 GROUP BY enrichmentStatus;

